const item = $('Скрипт: зібрати інсталяцію').first().json;
const st = ($json.server_types || [])[0];
const chat = String($('Вхід: параметри деплою').first().json.chat_space || '');

if (!st) {
  return [{ json: { abort: true, chat_space: chat, message: '⚠️ Тариф "' + item.server_type + '" не знайдено в Hetzner. Деплой не запущено. Перегляньте доступні тарифи командою «покажи тарифи».' } }];
}

const EU = ['nbg1', 'fsn1', 'hel1'];
const avail = (st.locations || []).filter(l => l.available).map(l => l.name);
const pick = EU.find(l => avail.indexOf(l) >= 0);

if (!pick) {
  return [{ json: { abort: true, chat_space: chat, message: '⚠️ Тариф ' + String(st.name || item.server_type).toUpperCase() + ' зараз недоступний у європейських локаціях (nbg1, fsn1, hel1). Доступно лише: ' + (avail.join(', ') || 'ніде') + '. Деплой не запущено. Оберіть інший тариф, наприклад cpx42.' } }];
}

const out = JSON.parse(JSON.stringify(item));
out.hetzner_body.location = pick;
out.location = pick;
out.chat_space = chat;
return [{ json: out }];
